<script>
document.addEventListener('DOMContentLoaded', function() {
    const weightInputs = document.querySelectorAll('.goal-weight-input');
    const indicator = document.getElementById('goals-weight-indicator');
    if (!weightInputs.length || !indicator) return;

    function recalculate() {
        let total = 0;
        let count = 0;
        weightInputs.forEach(input => {
            const val = parseFloat(input.value);
            if (!isNaN(val) && val > 0) {
                total += val;
                count++;
            }
        });

        if (total === 100) {
            indicator.className = 'badge bg-success bg-opacity-10 text-success border border-success py-2 px-3';
            indicator.innerHTML = '<i class="bi bi-check-circle me-1"></i>المجموع: 100% (متطابق تماماً)';
        } else if (total > 0) {
            indicator.className = 'badge bg-primary bg-opacity-10 text-primary border border-primary py-2 px-3';
            indicator.innerHTML = '<i class="bi bi-magic me-1"></i>المجموع المدخل: ' + total + '% ➔ سيتم موازنتها تلقائياً لتساوي 100%';
        } else {
            indicator.className = 'badge bg-light text-primary border py-2 px-3';
            indicator.innerHTML = '<i class="bi bi-magic me-1"></i>يتم توزيع الأوزان تلقائياً بالتساوي (100%)';
        }
    }

    weightInputs.forEach(input => {
        input.addEventListener('input', recalculate);
    });
    recalculate();
});
</script>
